data = [
    (2.1, 0), (3.4, 0), (5.0, 1), (5.5, 1), (1.0, 0), (6.2, 1), (4.0, 0), (4.8, 1),
]

def crear_umbral(t):
    def clf(x):
        return 1 if x >= t else 0
    return clf

def precision(clf, data):
    correctos = sum(1 for x, y in data if clf(x) == y)
    return correctos / len(data)

candidatos = {}
for t in [3.0, 4.0, 4.5, 5.0]:
    clf = crear_umbral(t)
    candidatos[f"umbral_{t}"] = precision(clf, data)

mejor = max(candidatos, key=candidatos.get)

for nombre, acc in sorted(candidatos.items()):
    print(f"{nombre}: precision={acc:.2f}")
print(f"Mejor modelo: {mejor} (precision={candidatos[mejor]:.2f})")
